<div class="customer-modal-backdrop"><section class="customer-modal" role="dialog" aria-modal="true"><div class="customer-modal-header"><div><span class="modal-eyebrow">Request correction</span><h2>Edit Advance Request</h2></div><a class="customer-modal-close" href="index.php?page=admin&amp;section=cashier-advance-requests">&times;</a></div><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="advance_request_action" value="update"><input type="hidden" name="request_id" value="<?= (int) $editRequest['id'] ?>"><div class="customer-modal-body"><div class="mb-3"><label class="form-label">Employee *</label><select class="form-select" name="employee_id" required><?php foreach ($employeeOptions as $option): ?><option value="<?= (int) $option['id'] ?>" <?= (int) $option['id'] === (int) $editRequest['employee_id'] ? 'selected' : '' ?>><?= e($option['name'].' ('.$option['employee_code'].')') ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label">Advance Date *</label><input class="form-control" type="date" name="advance_date" value="<?= e($editRequest['advance_date']) ?>" required></div><div class="mb-3"><label class="form-label">Amount (Rs.) *</label><input class="form-control" type="number" name="amount" min=".01" step=".01" value="<?= e((string) $editRequest['amount']) ?>" required></div><div class="mb-3"><label class="form-label">Status *</label><select class="form-select" name="status" required><option value="pending" <?= $editRequest['status'] === 'pending' ? 'selected' : '' ?>>Pending</option><option value="approved" <?= $editRequest['status'] === 'approved' ? 'selected' : '' ?>>Approved</option><option value="rejected" <?= $editRequest['status'] === 'rejected' ? 'selected' : '' ?>>Rejected</option></select></div><div><label class="form-label">Reason</label><textarea class="form-control" name="reason" rows="3"><?= e($editRequest['reason'] ?? '') ?></textarea></div></div><div class="customer-modal-footer"><a class="btn btn-light" href="index.php?page=admin&amp;section=cashier-advance-requests">Cancel</a><button class="btn btn-primary">Save Changes</button></div></form></section></div>
